<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$posts=load_json('blog.json',[]);$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$id=sanitize($_POST['id']??'');$action=sanitize($_POST['action']??'');if($id&&$action==='delete'&&delete_json_item('blog.json',fn($post)=>is_array($post)&&($post['id']??'')===$id))$message='Post deleted.';elseif($id&&$action==='delete')$error='The post could not be deleted.';}?>
<main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?>"><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a class="active" href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>Blog editor</h1><small style="color:var(--subtle)">Publish and maintain articles</small></div><a class="button button-primary button-small" href="<?= e(app_url('admin/blog-add.php')) ?>">New post</a></header><div class="admin-content"><section class="admin-card admin-table-card"><div class="table-wrap"><table><thead><tr><th>Post</th><th>Author</th><th>Published</th><th>Actions</th></tr></thead><tbody><?php if(!$posts):?><tr><td colspan=4><div class="empty-state"><h3>No posts</h3><p>Create the first article.</p></div></td></tr><?php else:foreach(array_reverse($posts) as $post):?><tr><td><strong><?= e(truncate((string)$post['title'],60)) ?></strong><br><small style="color:var(--subtle)"><?= e(truncate((string)$post['slug'],70)) ?></small></td><td><?= e((string)$post['author']) ?></td><td><?= e(format_date((string)$post['published_at'])) ?></td><td><div class="admin-actions"><a href="<?= e(app_url('admin/blog-edit.php?id='.rawurlencode((string)$post['id']))) ?>">Edit</a><button type=button data-confirm="<?= e(app_url('admin/blog.php?action=delete&id='.rawurlencode((string)$post['id']))) ?>">Delete</button></div></td></tr><?php endforeach;endif; ?></tbody></table></div></section><?php if($error):?><div class="alert error" style="margin-top:18px"><?= e($error) ?></div><?php elseif($message):?><div class="alert success" style="margin-top:18px"><?= e($message) ?></div><?php endif; ?></div></div><div class="modal" data-modal aria-hidden=true><div class="modal-card"><h2>Delete post?</h2><p>The article will be removed from the public blog.</p><form id=confirm-form method=post><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=action value=delete><input type=hidden name=id value=""><div class="modal-actions"><button class="button button-ghost" type=button data-close-modal>Cancel</button><button class="button button-primary" type=submit>Delete post</button></div></form></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
